// Only limit and before are read: any userId the client sends is dropped, since the list is always the connection's user's.
function validateListSessionsMessage(message: Record<string, unknown>): ValidationResult {
  const data: ListSessionsMessage = {type: 'list_sessions'};

  if (message.limit !== undefined) {
    if (typeof message.limit !== 'number' || !Number.isInteger(message.limit) || message.limit < 0) {
      return {valid: false, error: 'list_sessions limit must be a non-negative integer'};
    }
    data.limit = message.limit;
  }

  if (message.before !== undefined) {
    const before = toSessionCursor(message.before);
    if (!before) {
      return {valid: false, error: 'list_sessions before must be {updatedAt, sessionId} naming a date and a session id'};
    }
    data.before = before;
  }

  return {valid: true, data};
}

function toSessionCursor(value: unknown): SessionCursor | undefined {
  if (typeof value !== 'object' || value === null) return undefined;
  const {updatedAt, sessionId} = value as Record<string, unknown>;
  if (typeof sessionId !== 'string' || sessionId.length === 0 || sessionId.length > MAX_SESSION_ID_LENGTH) return undefined;
  if (typeof updatedAt !== 'string' && typeof updatedAt !== 'number') return undefined;
  if (!Number.isFinite(new Date(updatedAt).getTime())) return undefined;
  return {updatedAt, sessionId};
}
'''
